-- The maps of Mercedes-Benz Stadium, State Farm Arena, Truist Park and Lincoln Financial Field (Sean, 2026-10-29: the seating
-- charts he sent as screenshots), read the same way as the others: each level's sections clockwise by side. We draw our own map; only
-- the numbers come from the charts. Truist Park is drawn with home plate at the bottom. Suites, lofts and standing room are left off.

update public.ve_venues set layout = '{"field": "football", "ring_m": 900, "levels": [{"level": "100", "name": "100 level", "sides": {"top": ["124", "C126", "C127", "C129", "C130", "132"], "right": ["136", "101", "102", "104"], "br": ["107"], "bottom": ["C109", "C111", "113"], "bl": ["114"], "left": ["116", "118", "119", "120", "121"], "tl": ["122"]}}, {"level": "200", "name": "200 level", "sides": {"tl": ["227", "228"], "top": ["231", "233", "C236", "C238", "241", "243"], "tr": ["247"], "br": ["202"], "bottom": ["205", "207", "C210", "C212", "215", "217"], "bl": ["219"]}}, {"level": "300", "name": "300 level", "sides": {"tl": ["329", "330", "331", "332", "334", "335"], "top": ["337", "338", "340", "341", "342"], "tr": ["344", "345", "346", "348", "349", "350"], "br": ["301", "302", "303"], "bottom": ["305", "306", "307", "309", "310", "312", "313", "314"], "bl": ["316", "317", "318", "320"], "left": ["324C", "325C", "326C", "327C", "328"]}}]}'::jsonb where slug = 'mercedes-benz-stadium';
